const fs=require('fs'),vm=require('vm'),path=require('path');
function harness(docs,person='P',hooks={}){
 const stats={get:0,batches:0,queries:0,recheck:0},need=(v,c)=>{if(!v)throw Object.assign(Error(c),{code:c})},cols={activity:'canonicalActivities',attendance:'activityAttendance',attendanceCollection:'activityAttendanceCollections',evidence:'migrationEvidence',cycle:'presentationCycles',academicSemester:'academicSemesters',frequencyPeriod:'activityFrequencyPeriods',justification:'activityJustifications'};
 const db={get(p){stats.get++;return docs[p]||null},getMany(paths){stats.batches++;return paths.map(p=>docs[p]||null)},query(q){stats.queries++;let rows=Object.entries(docs).filter(([p,d])=>p.split('/').length===2&&p.startsWith(q.collection+'/')&&(q.filters||[]).every(f=>f.field.split('.').reduce((v,k)=>v?.[k],d)===f.value)).sort(([a],[b])=>a.localeCompare(b));if(q.cursor)rows=rows.filter(([p])=>p.split('/').at(-1)>q.cursor[0].name.split('/').at(-1));return rows.slice(0,q.limit).map(([p,d])=>({data:d}));}};
 const ctx=vm.createContext({f4ActivitiesModel_:()=>({need,ref:(kind,id)=>({kind,id}),stamp:v=>v,path:r=>cols[r.kind]+'/'+r.id,id:v=>typeof v==='string'&&/^[A-Za-z0-9_-]+$/.test(v),ms:v=>typeof v==='number'?v:v?.toMillis?v.toMillis():(v?._seconds||0)*1000,civil:v=>need(/^\d{4}-\d{2}-\d{2}$/.test(v),'VALIDATION_ERROR')}),f4Core_:()=>({exact:(v,keys)=>need(Object.keys(v).sort().join()===keys.slice().sort().join(),'VALIDATION_ERROR')}),f4Firestore_:()=>({connect:()=>db,DocumentReference:class{constructor(name){this.name=name}}}),f4DevBoundary_:()=>({root:''}),Utilities:{formatDate:()=> '12:00'},f4AttendanceExceptionalWindow_:()=>null});
 for(const n of ['131_activity_attendance','133_act_portal_compat','198_act_context_actions','137_act_frequency_compat','152_act_activity_read_views','177_act_justification_pairing','176_act_academic_governance']){const dir=path.resolve(__dirname,'../../../../activities/v2'),file=fs.readdirSync(dir).find(f=>f.startsWith(n));if(!file)throw Error(n);vm.runInContext(fs.readFileSync(path.join(dir,file),'utf8'),ctx);}
 const reader=ctx.f4ActivitiesFrequencyCompat_({config:{projectId:'demo'},clock:()=>Date.UTC(2026,10,1),ports:{readWithAuthoritySnapshot:fn=>fn(()=>{},p=>docs[p]),commandAccess:(...args)=>hooks.commandAccess?.(...args)===true,readAuthority(...args){hooks.authority?.(...args);return {personId:person}},recheckAuthority(){stats.recheck++;hooks.recheck?.()}}});
 return {ctx,reader,stats,db,read:()=>JSON.parse(JSON.stringify(reader.read('/v2/minha-frequencia'))).data};
}
module.exports={harness};
